// Ref: #/components/schemas/SnatchPolicy
type SnatchPolicy struct {
	// How many missing items one snatch goes after (0 disables missing snatches).
	MissingPerCycle int `json:"missing_per_cycle"`
	// How many cutoff-unmet items one snatch goes after (0 disables upgrade snatches).
	UpgradePerCycle int `json:"upgrade_per_cycle"`
	// Refractory period: seconds between two snatches of the same kind.
	CycleIntervalS int `json:"cycle_interval_s"`
	// Stamina: searches an instance may send to its indexers per hour before it needs a rest (1-500).
	// One per episode, season, movie, album or book; one for a whole artist or author search.
	HourlyCap int `json:"hourly_cap"`
	// Random spreads searches over the library, sequential walks it with a cursor, recent prefers the
	// newest releases with a slice reserved for the backlog.
	Selection          SnatchPolicySelection         `json:"selection"`
	MonitoredOnly      bool                          `json:"monitored_only"`
	SkipFutureReleases bool                          `json:"skip_future_releases"`
	RadarrReleaseType  SnatchPolicyRadarrReleaseType `json:"radarr_release_type"`
	SonarrMissingMode  SnatchPolicySonarrMissingMode `json:"sonarr_missing_mode"`
	SonarrUpgradeMode  SnatchPolicySonarrUpgradeMode `json:"sonarr_upgrade_mode"`
	// Search grouping for Lidarr missing runs; upgrade runs always search per album.
	LidarrMissingMode SnatchPolicyLidarrMissingMode `json:"lidarr_missing_mode"`
	// Afterglow: hours an item rests after a snatch before it may be touched again.
	ProcessedTTLH int  `json:"processed_ttl_h"`
	MaxQueueSize  int  `json:"max_queue_size"`
	AwaitCommand  bool `json:"await_command"`
	PageSize      int  `json:"page_size"`
	// Skip items the *arr grabbed within this many hours (its history) and items already in its download
	// queue; 0 keeps only the queue check.
	RecentGrabWindowH int `json:"recent_grab_window_h"`
	// Afterglow doubles after every fruitless snatch of the same item, up to this many hours.
	AfterglowMaxH int `json:"afterglow_max_h"`
	// *arr tag ids: when not empty, only items carrying one of these tags are searched. An episode,
	// album or book has the tags of its series, artist or author. Absent = empty.
	IncludeTags []int32 `json:"include_tags"`
	// *arr tag ids: items carrying any of these tags are never searched. An id may not be in both tag
	// lists. Absent = empty.
	ExcludeTags []int32 `json:"exclude_tags"`
	// *arr quality profile ids: when not empty, only items using one of these profiles are searched. An
	// episode, album or book uses the profile of its series, artist or author; a Chaptarr author counts
	// its audiobook and ebook profiles too. Absent = empty.
	IncludeQualityProfiles []int32 `json:"include_quality_profiles"`
	// *arr quality profile ids: items using any of these profiles are never searched. An id may not be
	// in both profile lists. Absent = empty.
	ExcludeQualityProfiles []int32 `json:"exclude_quality_profiles"`
	// Skip items released less than this many hours ago; 0 (or absent) turns the delay off. The release
	// date is the one of the app kind: air date (Sonarr, Whisparr v2), the date of radarr_release_type
	// (Radarr, Whisparr v3), the album or book release date. Items without a date are kept.
	ReleaseDelayH OptInt `json:"release_delay_h"`
	// When true, planner creates preview / dry-run runs that do not dispatch searches.
	DryRun OptBool `json:"dry_run"`
	// Radarr only: skip movies Radarr reports as not yet available (isAvailable false, the movie's
	// minimum availability is not reached). They are not searched and cost no stamina. Movies without
	// the flag are searched. Absent = true.
	SkipUnavailableMovies OptBool     `json:"skip_unavailable_movies"`
	UpdatedAt             OptDateTime `json:"updated_at"`
}

